<?php
declare(strict_types=1);
namespace AIcontrol;
use AIcontrolWorkspaceUi as Ui;

/** Everyday work is an owner-led pathway, with progressive reading and native forms. */
final class EverydayEngineeringView
{
    private static int $field=0;
    private static string $csrf='';
    private static int $project=0;
    private static function e(mixed $value): string {return Ui::e((string)$value);}
    private static function form(string $action,array $fields=[],bool $ai=false): void
    {
        echo '<form method="post" enctype="multipart/form-data" action="/loader.php?view=nasa" data-everyday-form'.($ai?' data-everyday-ai':'').'>'.self::$csrf;
        foreach(['action'=>$action,'nasa_project'=>self::$project]+$fields as $key=>$value)echo '<input type="hidden" name="'.self::e($key).'" value="'.self::e($value).'">';
    }
    private static function input(string $name,string $label,string $value='',int $max=160,bool $area=false,bool $required=true): void
    {
        $id='everyday-field-'.++self::$field;echo '<label class="form-label" for="'.$id.'">'.self::e($label).'</label>';
        if($area)echo '<textarea class="form-control" id="'.$id.'" name="'.self::e($name).'" maxlength="'.$max.'" rows="4"'.($required?' required':'').'>'.self::e($value).'</textarea>';
        else echo '<input class="form-control" id="'.$id.'" name="'.self::e($name).'" maxlength="'.$max.'" value="'.self::e($value).'"'.($required?' required':'').'>';
    }
    private static function submit(string $label,string $class='btn-outline-primary',bool $disabled=false): void {echo '<button class="btn '.$class.'"'.($disabled?' disabled':'').'>'.self::e($label).'</button></form>';}
    private static function chip(string $label,string $level=''): string {return '<span class="nasa-chip '.self::e($level).'">'.self::e($label).'</span>';}
    private static function scopeLabel(string $scope): string
    {
        return ['unknown'=>'Not established','fixture'=>'Synthetic fixture only','synthetic_fixture'=>'Synthetic fixture only','local'=>'Local test environment','local_test'=>'Local test environment','live_provider'=>'Live provider request','hosted'=>'Hosted website','hosted_test'=>'Hosted website','manual'=>'Manual user observation','user_observation'=>'Manual user observation','web_source'=>'Captured web source, not a local/hosted test','other'=>'Other explicitly recorded scope'][$scope]??str_replace('_',' ',$scope);
    }
    private static function textList(array $items,string $empty=''): void
    {
        if(!$items){if($empty!=='')echo '<p class="nasa-hint">'.self::e($empty).'</p>';return;}
        echo '<ul>';foreach($items as $item)if(is_scalar($item))echo '<li>'.self::e($item).'</li>';echo '</ul>';
    }
    private static function picker(array $data,?array $source): void
    {
        echo '<form method="get" action="/loader.php" class="nasa-project-picker"><input type="hidden" name="view" value="nasa"><label for="everyday-project">Project</label><select class="form-select" id="everyday-project" name="source">';
        foreach($data['sources']??[] as $candidate){$key=$candidate['kind'].':'.$candidate['id'];$selected=$source&&$key===($source['kind']??$source['source_kind']??'').':'.($source['id']??$source['source_id']??'');echo '<option value="'.self::e($key).'"'.($selected?' selected':'').'>'.self::e($candidate['name'].' · '.($candidate['kind']==='research'?'Research':'Tasks')).'</option>';}
        echo '</select><button class="btn btn-outline-primary">Open project</button></form>';
    }
    private static function promotionFields(): array
    {
        $fields=[];foreach(['promote_run','promote_node'] as $name){$value=$_GET[$name]??null;if(!is_string($value)||!preg_match('/^[1-9][0-9]{0,9}$/D',$value))return [];$fields[$name]=$value;}return $fields;
    }
    private static function cyclePicker(array $cycles,array $selected): void
    {
        echo '<form method="get" action="/loader.php#everyday-cycle" class="nasa-project-picker"><input type="hidden" name="view" value="nasa"><input type="hidden" name="nasa_project" value="'.self::$project.'"><label for="everyday-cycle-inspection">Inspect an adopted cycle</label><select class="form-select" id="everyday-cycle-inspection" name="engineering_cycle">';
        foreach($cycles as $cycle){$key=$cycle['object_key']??$cycle['key'];$payload=self::objectData($cycle);$forecast=!($payload['commitment_refs']??$payload['details']['commitment_refs']??[]);echo '<option value="'.self::e($key).'"'.($key===($selected['object_key']??$selected['key'])?' selected':'').'>'.self::e($key.' · '.$cycle['title'].' · '.($forecast?'forecast / no commitments':str_replace('_',' ',$cycle['state']))).'</option>';}
        echo '</select><button class="btn btn-outline-primary">Inspect cycle</button></form><p class="nasa-hint">Inspection changes only what you are reading. Starting or changing a cycle still requires a separate owner decision.</p>';
    }
    public static function welcome(array $data,string $csrf): void
    {
        self::$csrf=$csrf;self::$project=0;self::$field=0;$source=$data['source']??null;
        echo '<div class="nasa-workspace everyday-workspace" data-everyday-workspace><div class="nasa-intro"><div><span class="nasa-eyebrow">EVERYDAY ENGINEERING</span><h2>A clear route, with evidence you can follow.</h2><p>The AI proposes useful progress. You choose the commitments and decide what the evidence supports.</p></div></div>';
        self::picker($data,$source);
        echo '<article class="card"><div class="card-body"><h3>Start from the outcome you want.</h3><p>Work in small cycles: agree the next outcome, inspect the evidence, then decide what happens next. Formal NASA phases and document gates remain available in NASA Managed.</p>';
        if($source){echo '<h4>'.self::e($source['name']).'</h4><p class="nasa-prewrap">'.self::e($source['brief']).'</p>';echo '<h4>The short working agreement you are adopting</h4><ul><li>You choose commitments and make approval, verification and cycle decisions.</li><li>AI proposes drafts and reports need explicit sources.</li><li>Review each chosen cycle before closure or replan.</li><li>Keep evidence scope, project versions and unresolved obligations visible.</li><li>Publishing, executing work and provider requests retain their existing controls; uncertain requests are not retried automatically.</li></ul>';self::form('nasa_everyday_start',['source_kind'=>$source['kind'],'source_id'=>$source['id']]+self::promotionFields());self::submit('Start everyday workspace','btn-primary');echo '<p class="nasa-hint">This uses the saved brief as your initial intent. It does not call AI, start work or approve evidence.</p><a href="/loader.php?view=nasa&amp;source='.self::e($source['kind'].':'.$source['id']).'&amp;nasa_mode=rigorous">Use NASA Managed for this project</a>';}
        else echo '<p>Create a task or research project first.</p><a class="btn btn-primary" href="/loader.php?view=projects#new-project">Create task project</a> <a class="btn btn-outline-primary" href="/loader.php?view=research&amp;new=1">Create research project</a>';
        echo '</div></article><article class="card"><div class="card-body"><h3>Understand every significant recommendation.</h3><p>Inspect the intent, promise, risk and evidence it used, then see the handbook principle and the practical consequence. AI recommendations stay pending until you adopt or reject them.</p></div></article></div>';
    }
    private static function objectData(array $object): array {return is_array($object['payload']??null)?$object['payload']:(is_array($object['data']??null)?$object['data']:[]);}
    private static function details(array $details): void
    {
        $labels=['outcome'=>'Outcome','scope'=>'Scope','exclusions'=>'Outside this cycle','entry_questions'=>'Entry questions','success_questions'=>'Success questions','entry'=>'Entry questions','success'=>'Success questions','planned_checks'=>'Planned checks','goal'=>'Goal','dependencies'=>'Dependencies','promise_refs'=>'Promises','risk_refs'=>'Risks','verification'=>'Verification approach','validation'=>'User validation approach','responsibilities'=>'Responsibilities','review_rhythm'=>'Review rhythm','release_rules'=>'Release agreement','constraints'=>'Constraints','non_goals'=>'Non-goals','users'=>'People this serves','checks'=>'Planned checks','significant_outcome'=>'Significant outcome','why_route'=>'Why this route','uncertainties'=>'Uncertainties that could change the route','cycle_refs'=>'Forecast cycle references','commitment_refs'=>'Chosen commitments','dependency_refs'=>'Dependencies','problem'=>'Problem to solve','boundaries'=>'Boundaries','evidence_rule'=>'Evidence agreement','change_rule'=>'Change agreement','release_rule'=>'Release agreement'];
        foreach($details as $key=>$value){if(!isset($labels[$key]))continue;echo '<h5>'.self::e($labels[$key]).'</h5>';if($key==='dependencies'&&is_array($value)){echo '<ul>';foreach($value as $dependency)if(is_array($dependency))echo '<li>'.self::e(($dependency['cycle_ref']??'Cycle').' depends on '.implode(', ',$dependency['depends_on']??[])).'</li>';echo '</ul>';}elseif(is_array($value))self::textList($value);elseif(is_scalar($value))echo '<p class="nasa-prewrap">'.self::e($value).'</p>';}
    }
    private static function ai(string $operation,string $label): void
    {
        self::form('nasa_everyday_ai',['operation'=>$operation],true);self::submit($label,'btn-outline-primary',!AgentRunner::configured());
    }
    private static function editObject(array $object,array $s): void
    {
        echo '<details><summary>Edit owner '.self::e($object['kind']==='intent'?'intent':'working agreement').'</summary><p>Save a new owner version. Pending advice based on an older intent or agreement must be reviewed again.</p>';
        self::form('nasa_everyday_object',['object_key'=>$object['object_key']??$object['key'],'version'=>$object['version'],'revision'=>$s['project']['revision']]);self::input('title','Record title',$object['title'],160);self::input('content',$object['kind']==='intent'?'Intent, desired outcome and boundaries':'Working agreement',$object['content'],$object['kind']==='intent'?5000:3000,true);self::submit('Save owner record version','btn-outline-primary');echo '</details>';
    }
    private static function objectCard(array $object,string $label='',bool $inspect=false): void
    {
        echo '<article class="card everyday-object" data-everyday-object="'.self::e($object['object_key']??$object['key']??'').'"><div class="card-body"><h4>'.self::e($object['title']??$label).'</h4>'.self::chip(str_replace('_',' ',$object['state']??'planned')).'<p class="nasa-prewrap"><strong>Saved planning description:</strong> '.self::e($object['content']??'').'</p>';
        $payload=self::objectData($object);self::details($payload['details']??$payload);echo '<p class="nasa-hint">'.self::e(($object['object_key']??$object['key']??'').' · version '.($object['version']??1).' · '.str_replace('_',' ',$object['created_by']??'owner')).'</p>';if($inspect)echo '<a href="/loader.php?view=nasa&amp;nasa_project='.self::$project.'&amp;engineering_cycle='.self::e($object['object_key']??$object['key']).'#everyday-cycle">Inspect '.self::e($object['object_key']??$object['key']).'</a>';echo '</div></article>';
    }
    private static function proposal(array $proposal): void
    {
        $p=$proposal['payload'];$pending=$proposal['status']==='pending';$fresh=(bool)($proposal['fresh']??false);$fields=['proposal_key'=>$proposal['proposal_key'],'version'=>$proposal['version']];
        echo '<article class="card everyday-proposal"><details'.($pending?' open':'').'><summary>'.self::e($proposal['proposal_key'].' · v'.$proposal['version'].' · '.str_replace('_',' ',$proposal['status'])).'</summary><div class="card-body"><h3>'.self::e($p['headline']).'</h3>'.self::chip($pending?'AI proposal · not adopted':'Owner disposition retained',$pending?'medium':'');
        echo '<h4>What next?</h4><p>'.self::e($p['next_move']['summary']).'</p><h4>Why now?</h4><p>'.self::e($p['next_move']['why_now']).'</p><h4>What would increase confidence?</h4><p>'.self::e($p['confidence_gap']).'</p>';
        foreach($p['owner_decisions'] as $decision)echo '<div class="nasa-finding"><h4>Your decision</h4><p>'.self::e($decision['question']).'</p><p class="nasa-hint">'.self::e($decision['consequence']).'</p></div>';
        if($pending&&!$fresh)echo '<p role="status">Project context changed. This proposal is retained for inspection; request a fresh proposal before adopting it.</p>';
        echo '<details><summary>Inspect the proposed change set</summary>';
        foreach($p['payload']['objects'] as $o){echo '<h4>'.self::e(ucfirst($o['kind']).' · '.$o['title']).'</h4><p class="nasa-prewrap">'.self::e($o['content']).'</p>';self::details($o['details']??[]);}
        foreach(['promises'=>'Proposed promises','risks'=>'Proposed risks','decisions'=>'Proposed decisions','checks'=>'Planned checks','findings'=>'Assessment findings','formality'=>'Proposed level of rigor'] as $key=>$title){$rows=$p['payload'][$key]??[];if(!$rows)continue;echo '<h4>'.self::e($title).'</h4>';foreach($rows as $row){echo '<div class="nasa-finding">';foreach($row as $field=>$value)if(is_scalar($value))echo '<p><strong>'.self::e(ucfirst(str_replace('_',' ',$field))).':</strong> '.self::e($value).'</p>';echo '</div>';}}
        echo '</details><details><summary>Assumptions and unknowns</summary><h4>Assumptions to confirm</h4>';self::textList($p['assumptions'],'None recorded in this proposal.');echo '<h4>Unknowns</h4>';self::textList($p['unknowns'],'None recorded; this does not establish completeness.');echo '</details>';
        echo '<a href="#everyday-why" data-everyday-open="why">Why this? Inspect the project and handbook trace</a>';
        if($pending){echo '<div class="nasa-package-actions">';self::form('nasa_everyday_proposal_accept',$fields);self::submit('Adopt this proposal as planning','btn-primary',!$fresh);self::form('nasa_everyday_proposal_reject',$fields);self::submit('Reject proposal','btn-outline-secondary');echo '</div><p class="nasa-hint">Adoption does not start a cycle, verify a promise, accept risk or execute work.</p>';
            if($fresh){echo '<details><summary>Advanced: edit the structured proposal</summary><p>Editing appends a pending version. Review and adopt the saved version separately.</p>';self::form('nasa_everyday_proposal_edit',$fields);self::input('proposal_json','Proposal JSON (compact to fit the bounded review)',json_encode($p,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),12000,true);self::submit('Save edited proposal','btn-outline-primary');echo '</details>';}}
        echo '</div></details></article>';
    }
    private static function reference(string $reference,array $s,array $w): void
    {
        $found=null;foreach(array_merge($s['items']??[],$w['objects']??[]) as $r){$key=$r['item_key']??$r['object_key']??$r['key']??'';$kind=$r['kind']??'';if($reference===$kind.':'.$key.':v'.($r['version']??1)){$found=$r;break;}}
        echo '<li><strong>'.self::e($found['title']??$reference).'</strong><p class="nasa-hint">'.self::e($reference).'</p>';if($found)echo '<p class="nasa-prewrap">'.self::e(mb_strcut($found['content']??'',0,1000,'UTF-8')).'</p>';else echo '<p class="nasa-hint">This reference is part of the retained proposal. Inspect its recorded context and version before adoption.</p>';echo '</li>';
    }
    private static function principles(array $ids): void
    {
        $catalog=class_exists(EverydayPrompt::class)?EverydayPrompt::principles():[];
        foreach($ids as $id){$principle=$catalog[$id]??null;if(!$principle){echo '<p>'.self::e(str_replace('_',' ',$id)).'</p>';continue;}
            $title=$principle['title']??$principle['name']??str_replace('_',' ',$id);$ref=$principle['ref']??$principle['reference']??'';$explanation=$principle['application']??$principle['detail']??$principle['description']??$principle['control']??$principle['short']??'';
            echo '<div class="nasa-finding"><h4>'.self::e($title).'</h4>';if(is_string($explanation))echo '<p>'.self::e($explanation).'</p>';echo '<p class="nasa-hint">Handbook '.self::e(is_array($ref)?implode(', ',$ref):$ref).' · knowledge '.self::e(NasaKnowledge::VERSION).'</p></div>';
        }
    }
    private static function cycleControls(array $cycle,array $commitments,array $s): void
    {
        echo '<details><summary>Owner cycle decision</summary><p>State changes retain the commitment configuration and a reason. Unresolved work must be explicitly carried, deferred or superseded when replanning or closing.</p>';
        self::form('nasa_everyday_cycle',['cycle_key'=>$cycle['object_key']??$cycle['key'],'version'=>$cycle['version'],'revision'=>$s['project']['revision']]);
        $id='everyday-field-'.++self::$field;echo '<label for="'.$id.'">What should happen to this cycle?</label><select class="form-select" id="'.$id.'" name="transition">';foreach(['start'=>'Start / resume this cycle','review'=>'Move to owner review','pause'=>'Pause this cycle','replan'=>'Replan this cycle','close'=>'Close with reviewed outcomes','close_incomplete'=>'Close as incomplete'] as $key=>$label)echo '<option value="'.$key.'">'.$label.'</option>';echo '</select>';self::input('reason','Reason, observed outcome and remaining limits','',2400,true);self::input('configuration_ref','Project configuration for this cycle (optional; separate from AIcontrol release)','',500,false,false);
        echo '<details><summary>Commitment dispositions for closure or replan</summary><p>Use the exact commitment keys shown below. Record whether each is carried, deferred with a trigger, or superseded by a named replacement.</p>';foreach($commitments as $c){$key=$c['key']??$c['object_key'];echo '<fieldset><legend>'.self::e($key.' · '.$c['title']).'</legend>';$field='everyday-field-'.++self::$field;echo '<label for="'.$field.'">Disposition for '.self::e($key).'</label><select class="form-select" name="dispositions['.self::e($key).'][action]" id="'.$field.'">';foreach(['carried_forward'=>'Carry forward unresolved','deferred'=>'Defer with a revisit trigger','superseded'=>'Supersede with a replacement','removed_from_scope'=>'Remove through an owner-decided scope choice'] as $action=>$label)echo '<option value="'.$action.'">'.$label.'</option>';echo '</select>';self::input('dispositions['.$key.'][reason]','Why this disposition?','',1600,true,false);self::input('dispositions['.$key.'][revisit]','When should it be revisited?','',1000,true,false);self::input('dispositions['.$key.'][replacement_ref]','Replacement or owner decision reference (when required)','',160,false,false);echo '</fieldset>';}echo '</details>';self::submit('Record owner cycle decision','btn-outline-primary');echo '</details>';
    }
    private static function observation(array $commitment,array $s): void
    {
        echo '<details><summary>Record what happened for '.self::e($commitment['title']).'</summary><p>This records an owner-reported work observation. It does not independently verify a promise or close the cycle.</p>';
        self::form('nasa_everyday_observation',['commitment_key'=>$commitment['object_key']??$commitment['key'],'version'=>$commitment['version'],'revision'=>$s['project']['revision']]);
        $field='everyday-field-'.++self::$field;echo '<label for="'.$field.'">Reported work state</label><select class="form-select" id="'.$field.'" name="state">';foreach(['reported_in_progress'=>'Reported in progress','reported_complete'=>'Reported complete','blocked'=>'Blocked','deferred'=>'Deferred'] as $state=>$label)echo '<option value="'.$state.'">'.$label.'</option>';echo '</select>';
        self::input('source','Observation source or result reference','',1000);
        $field='everyday-field-'.++self::$field;echo '<label for="'.$field.'">Observed scope</label><select class="form-select" id="'.$field.'" name="scope">';foreach(['unknown'=>'Not established — choose the observed scope','fixture'=>'Synthetic fixture only','local'=>'Local test environment','live_provider'=>'Live provider request','hosted'=>'Hosted website','manual'=>'Manual user observation'] as $scope=>$label)echo '<option value="'.$scope.'">'.$label.'</option>';echo '</select>';
        self::input('observation','What was actually reported or observed?','',2400,true);self::input('limitations','Limitations and what remains unproven','',1600,true);self::input('configuration_ref','Tested project configuration (optional; never assume the control panel version)','',500,false,false);self::submit('Record owner-reported observation','btn-outline-primary');echo '</details>';
    }
    private static function verify(array $r): void
    {
        $d=$r['data'];echo '<details><summary>Owner verification decision for '.self::e($r['item_key']).'</summary><p>Link and review suitable evidence first. Confirmation concerns this exact promise, method, scope and project configuration; it does not prove other environments.</p>';
        self::form('nasa_save_record',['kind'=>'requirement','item_key'=>$r['item_key'],'version'=>$r['version'],'title'=>$r['title'],'content'=>$r['content'],'source'=>$d['source'],'method'=>$d['method'],'configuration_required'=>($d['configuration_required']??false)?'1':'0']);
        self::input('evidence','Actual evidence / result reference',$d['evidence']??'',2000,true,false);
        $id='everyday-field-'.++self::$field;echo '<label for="'.$id.'">Required evidence scope</label><select class="form-select" id="'.$id.'" name="required_scope">';foreach(['unknown'=>'Not established','fixture'=>'Synthetic fixture','local'=>'Local environment','live_provider'=>'Live provider','hosted'=>'Hosted website','manual'=>'Manual user observation'] as $scope=>$label)echo '<option value="'.$scope.'"'.(($d['required_scope']??'unknown')===$scope?' selected':'').'>'.$label.'</option>';echo '</select>';
        self::input('required_configuration_ref','Project configuration required by this promise',$d['required_configuration_ref']??'',500,false,false);
        $id='everyday-field-'.++self::$field;echo '<label for="'.$id.'">Verification state</label><select class="form-select" id="'.$id.'" name="status"><option value="unverified">Unverified</option><option value="verified">Verified — explicitly confirmed by me</option></select>';
        $id='everyday-field-'.++self::$field;echo '<label for="'.$id.'"><input id="'.$id.'" type="checkbox" name="verification_confirmed" value="1"> I confirm this exact promise and method are supported by the reviewed evidence, required scope and configuration.</label>';self::submit('Save owner verification decision','btn-outline-primary');echo '</details>';
    }
    private static function risks(array $s,array $w): void
    {
        $risks=array_values(array_filter($w['working_items']??$s['items']??[],static fn($r)=>$r['kind']==='risk'&&$r['status']!=='closed'&&$r['created_by']!=='ai_draft'));
        echo '<article class="card"><div class="card-body"><h3>What could still get in the way?</h3>';
        if(!$risks)echo '<p>No owner-adopted risk assessment is recorded. This does not establish low risk or absence of uncertainty.</p>';
        foreach($risks as $risk){$d=$risk['data'];$assessed=($d['rating_status']??'assessed')!=='not_assessed'&&is_numeric($d['residual_likelihood']??null)&&is_numeric($d['residual_consequence']??null);echo '<div class="nasa-finding"><h4>'.self::e($risk['title']).'</h4>'.self::chip($assessed?'Recorded residual exposure: '.($d['residual_likelihood']*$d['residual_consequence']).'/25':'Residual exposure not assessed','medium').'<p>'.self::e($risk['content']).'</p><p><strong>Response:</strong> '.self::e($d['mitigation']??'Not recorded').'</p><p class="nasa-hint">State: '.self::e($risk['status']).'. A proposed response is not an observed reduction in risk.</p></div>';}
        echo '</div></article>';
    }
    private static function results(array $s,array $w): void
    {
        $promises=array_values(array_filter($w['working_items']??$s['items']??[],static fn($r)=>$r['kind']==='requirement'&&$r['created_by']!=='ai_draft'));
        echo '<h3>What happened, what it supports, and what remains unknown</h3><p>Source observations, owner review and current verification are separate. A fixture result does not establish live-provider or hosted behaviour.</p>';
        foreach($w['results']??[] as $result){echo '<article class="card everyday-observation"><div class="card-body"><h4>Reported work · '.self::e($result['commitment_key']??'commitment').'</h4>'.self::chip(str_replace('_',' ',$result['work_state']??'reported')).'<p><strong>Observation:</strong> '.self::e($result['observation']??'').'</p><p><strong>Source:</strong> '.self::e($result['source']??'Owner report').'</p><p><strong>Scope:</strong> '.self::e(self::scopeLabel($result['scope']??'unknown')).'</p><p><strong>Tested project configuration:</strong> '.self::e($result['configuration_ref']??'Unknown').'</p><p><strong>Limitations:</strong> '.self::e($result['limitations']??'Not recorded').'</p><p class="nasa-hint">Owner-reported work; this does not verify a promise, accept risk or close a cycle.</p></div></article>';}
        if(!$promises)echo '<article class="card"><div class="card-body"><p>No owner-adopted promises are recorded yet. Review a cycle proposal to choose the behaviour to check.</p></div></article>';
        foreach($promises as $r){$verified=(bool)($r['verification_confirmed']??false);foreach($s['items']??[] as $current)if($current['kind']==='requirement'&&$current['item_key']===$r['item_key']&&(int)$current['version']===(int)$r['version'])$verified=(bool)($current['verification_confirmed']??false);$links=array_values(array_filter($s['provenance']??[],static fn($l)=>$l['item_kind']==='requirement'&&$l['item_key']===$r['item_key']));echo '<article class="card everyday-result"><div class="card-body"><h4>'.self::e($r['title']).'</h4>'.self::chip($verified?'Owner-confirmed for this promise':'Unverified',$verified?'low':'medium').'<p>'.self::e($r['content']).'</p><p><strong>Check:</strong> '.self::e($r['data']['method']).' · <strong>Required scope:</strong> '.self::e(self::scopeLabel($r['data']['required_scope']??'unknown')).' · <strong>Promise version:</strong> '.(int)$r['version'].'</p>';
            if(!$links)echo '<p><strong>Recorded observation:</strong> none linked to this promise.</p><p class="nasa-hint">A planned check or completed task alone cannot establish verification.</p>';
            foreach($links as $l){$source=$l['source_snapshot']??$l['snapshot']??[];$meta=$l['evidence_metadata']??[];$current=($l['source_current']??false)&&($l['subject_current']??false);echo '<div class="nasa-finding"><h5>'.self::e($source['title']??'Captured evidence record').'</h5><p><strong>Observation:</strong> '.self::e($source['content']??'No observation text retained.').'</p><p><strong>Scope:</strong> '.self::e(self::scopeLabel($meta['evidence_scope']??$source['evidence_scope']??'unknown')).'</p><p><strong>Review:</strong> '.self::e(($l['reviewed']??false)?'Owner review retained':'Not owner-reviewed').' · '.self::e($current?'Current subject/source match':'Historical or changed subject/source').'</p><p class="nasa-hint">'.self::e($source['reference']??'').'</p><p><strong>Tested project configuration:</strong> '.self::e(($meta['configuration_ref']??$source['configuration_ref']??'')?:'Not recorded').'</p><p><strong>Limitations:</strong> '.self::e(($meta['limitations']??$source['limitations']??'')?:'Not recorded; retain the source limits.').'</p></div>';}
            echo '<details><summary>Evidence and provenance details</summary>';if(class_exists(NasaIntegrationView::class))NasaIntegrationView::links($s,$r,self::$csrf);echo '</details>';self::verify($r);echo '<a href="#everyday-why" data-everyday-open="why">Trace the recommendation and handbook use</a></div></article>';
        }
    }
    private static function history(array $w): void
    {
        foreach($w['result_history']??[] as $result){echo '<details class="card everyday-observation-history"><summary>Owner-reported observation · '.self::e(($result['result_key']??'Result').' v'.($result['version']??1).' · '.($result['commitment_key']??'commitment')).'</summary><div class="card-body"><p><strong>Reported state:</strong> '.self::e(str_replace('_',' ',$result['work_state']??'reported')).'</p><p><strong>Observation:</strong> '.self::e($result['observation']??'').'</p><p><strong>Source:</strong> '.self::e($result['source']??'Owner report').'</p><p><strong>Scope:</strong> '.self::e(self::scopeLabel($result['scope']??'unknown')).'</p><p><strong>Tested project configuration:</strong> '.self::e(($result['configuration_ref']??'')?:'Unknown / not captured').'</p><p><strong>Limitations:</strong> '.self::e($result['limitations']??'Not recorded').'</p><p class="nasa-hint">This retained owner report does not independently verify a promise or close a cycle.</p></div></details>';}
        foreach($w['cycle_events']??[] as $event){$configuration=$event['configuration']??json_decode($event['configuration_json']??'{}',true);$dispositions=$event['dispositions']??json_decode($event['dispositions_json']??'{}',true);echo '<details class="card"><summary>Cycle owner event · '.self::e(($event['cycle_key']??'').' · '.str_replace('_',' ',$event['event']??'decision')).'</summary><div class="card-body"><p>'.self::e($event['reason']??'').'</p><p><strong>Managed project configuration:</strong> '.self::e(($configuration['project_code_ref']??'')?:'Unknown / not captured').'</p><p class="nasa-hint">AIcontrol release: '.self::e(($configuration['control_panel_sha']??'')?:'Not available').'. This is separate from the project version.</p>';if(is_array($dispositions))foreach($dispositions as $key=>$d)if(is_array($d))echo '<p><strong>'.self::e($key).':</strong> '.self::e(str_replace('_',' ',$d['action']??'')).' · '.self::e($d['reason']??'').' Revisit: '.self::e($d['revisit']??'').'</p>';echo '</div></details>';}
        foreach($w['history']??$w['objects']??[] as $o){echo '<details class="card"><summary>'.self::e(($o['object_key']??$o['key']??'').' v'.($o['version']??1).' · '.($o['title']??'').' · '.str_replace('_',' ',$o['state']??'recorded')).'</summary>';self::objectCard($o);echo '</details>';}
        foreach($w['proposal_history']??$w['proposals']??[] as $p)echo '<details class="card"><summary>'.self::e($p['proposal_key'].' v'.$p['version'].' · '.$p['operation'].' · '.$p['status']).'</summary><div class="card-body"><h4>'.self::e($p['payload']['headline']??'Retained recommendation').'</h4><p>'.self::e($p['payload']['next_move']['why_now']??'').'</p><p class="nasa-hint">'.self::e(str_replace('_',' ',$p['created_by']??'')).' · input context '.self::e($p['context_hash']??'not available').'</p></div></details>';
        foreach($w['profile_history']??[] as $profile)echo '<details class="card"><summary>Owner operating-mode decision · version '.(int)$profile['version'].' · '.self::e($profile['mode']).'</summary><div class="card-body"><p>'.self::e($profile['reason']).'</p><p><strong>Remaining exposure:</strong> '.self::e($profile['exposure']).'</p><p><strong>Revisit:</strong> '.self::e($profile['revisit']).'</p></div></details>';
    }
    public static function render(array $data,string $csrf): void
    {
        self::$csrf=$csrf;self::$field=0;$s=$data['workspace'];self::$project=(int)$s['project']['id'];$w=$s['everyday']??[];$groups=$w['groups']??[];$intent=$groups['intent'][0]??null;$pathway=$groups['pathway'][0]??null;$cycles=$groups['cycle']??[];$commitments=$groups['commitment']??[];$proposals=$w['proposals']??[];$active=$w['active_cycle']??null;$current=$active??($w['current_cycle']??($cycles[0]??null));$defaultCycle=$current;$selection=$_GET['engineering_cycle']??null;if(is_string($selection))foreach($cycles as $cycle)if(($cycle['object_key']??$cycle['key'])===$selection){$current=$cycle;break;}
        echo '<div class="nasa-workspace everyday-workspace" data-everyday-workspace><div class="nasa-intro"><div><span class="nasa-eyebrow">EVERYDAY ENGINEERING</span><h2>A clear route, with evidence you can follow.</h2><p>The AI keeps a proposed pathway. You choose commitments and control every approval, verification and cycle decision.</p></div>'.self::chip('Everyday work').'</div>';
        self::picker($data,['kind'=>$s['project']['source_kind'],'id'=>$s['project']['source_id']]);
        if($intent){echo '<details class="card"><summary>Read and correct the intent</summary><div class="card-body">';self::objectCard($intent);self::editObject($intent,$s);echo '</div></details>';}
        echo '<article class="card"><div class="card-body"><h3>'.self::e($s['project']['source']['name']).'</h3><p><strong>Intent:</strong> '.self::e($intent['content']??$s['project']['source']['brief']).'</p><p><strong>Current cycle:</strong> '.self::e($active?($active['object_key']??$active['key']).' · '.$active['title']:'No cycle is active. Choose a proposed cycle before starting work.').'</p><div class="nasa-package-actions">';self::ai('pathway','Propose pathway');self::ai('cycle','Design next cycle');self::ai('posture','Review current posture');echo '</div><p class="nasa-hint">One tool-free request per action; the existing 8/hour workspace and $1/source-project/day allowance applies. Proposals do not execute work. '.(!AgentRunner::configured()?'<a href="/loader.php?view=admin">Connect OpenAI in Admin</a> to request a proposal.':'').'</p><p role="status" aria-live="polite" data-everyday-operation></p></div></article>';
        if(self::promotionFields()&&class_exists(NasaIntegrationView::class))NasaIntegrationView::promote($s,self::$csrf);
        echo '<nav class="nasa-tabs" aria-label="Everyday engineering views" data-everyday-tabs>';foreach(['pathway'=>'Pathway','cycle'=>'Current cycle','results'=>'Results','why'=>'Why this?','history'=>'History'] as $key=>$label)echo '<a href="#everyday-'.$key.'" id="everyday-tab-'.$key.'" data-everyday-tab="'.$key.'">'.$label.'</a>';echo '</nav>';
        echo '<section id="everyday-pathway" data-everyday-panel="pathway"><h3>The route and the next useful move</h3>';self::risks($s,$w);
        if(!$proposals&&!$pathway)echo '<article class="card"><div class="card-body"><p>Start with a proposed pathway toward the outcome. It can contain a small cycle and planned checks without producing formal documents.</p></div></article>';
        foreach($proposals as $p)self::proposal($p);
        if($pathway)self::objectCard($pathway,'Adopted pathway');echo '<div class="nasa-record-grid">';foreach($cycles as $cycle)self::objectCard($cycle,'',true);echo '</div></section>';
        $cycleCommitments=$commitments;if($current){$currentPayload=self::objectData($current);$refs=$currentPayload['commitment_refs']??$currentPayload['details']['commitment_refs']??[];$keys=[];foreach($refs as $ref)if(preg_match('/^commitment:([^:]+):v[0-9]+$/D',$ref,$match))$keys[]=$match[1];$cycleCommitments=array_values(array_filter($commitments,static fn($c)=>in_array($c['key']??$c['object_key'],$keys,true)));}
        echo '<section id="everyday-cycle" data-everyday-panel="cycle"><h3>One manageable cycle at a time</h3>';
        if(!$cycles)echo '<p>No cycle has been adopted yet. Review a proposed cycle on Pathway.</p>';
        if($current){self::cyclePicker($cycles,$current);echo '<p><strong>Inspecting:</strong> '.self::e($current['title']).'</p>';self::objectCard($current);$currentKey=$current['object_key']??$current['key'];$obligations=$w['cycle_obligations_by_cycle'][$currentKey]??(($defaultCycle&&$currentKey===($defaultCycle['object_key']??$defaultCycle['key']))?($w['cycle_obligations']??[]):[]);if($cycleCommitments)self::cycleControls($current,$obligations,$s);else echo '<p class="nasa-hint">This is a forecast without concrete commitments. Use Design next cycle, then review and adopt the detailed proposal before starting it.</p>';}if($cycleCommitments){echo '<h3>Chosen commitments</h3>';foreach($cycleCommitments as $c){self::objectCard($c);self::observation($c,$s);}}foreach($groups['agreement']??[] as $agreement){echo '<details><summary>Our working agreement</summary>';self::objectCard($agreement);self::editObject($agreement,$s);echo '</details>';}echo '</section>';
        echo '<section id="everyday-results" data-everyday-panel="results">';self::results($s,$w);echo '</section>';
        echo '<section id="everyday-why" data-everyday-panel="why"><h3>How the project and textbook informed this advice</h3><p>A citation alone is not proof. Inspect the project facts, the proposed practical consequence and the owner decision needed.</p>';
        foreach($proposals as $p){$payload=$p['payload'];echo '<article class="card"><div class="card-body"><h4>'.self::e($payload['headline']).'</h4><p><strong>Why now:</strong> '.self::e($payload['next_move']['why_now']).'</p><h5>Project records used</h5><ol>';foreach($payload['next_move']['record_refs'] as $ref)self::reference($ref,$s,$w);echo '</ol><h5>Handbook principles applied</h5>';self::principles($payload['next_move']['principle_ids']);echo '<p><strong>Practical consequence:</strong> '.self::e($payload['next_move']['summary']).'</p><p><strong>Evidence or confidence still needed:</strong> '.self::e($payload['confidence_gap']).'</p><details><summary>Recorded context and versions</summary><pre class="nasa-prewrap">'.self::e(json_encode($p['manifest']??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)).'</pre></details></div></article>';}
        if(!$proposals)echo '<p>Request a proposal to see its actual project references, assumptions and handbook applications here.</p>';echo '<p><a href="'.NasaKnowledge::SOURCE.'" target="_blank" rel="noopener noreferrer">Read the official NASA Systems Engineering Handbook</a> · Original software adaptations, not NASA affiliation, certification or approval.</p><div class="nasa-package-actions">';self::ai('drift','Inspect possible drift');self::ai('formality','Review the level of rigor');echo '</div></section>';
        echo '<section id="everyday-history" data-everyday-panel="history"><h3>What changed, and who decided?</h3><p>Adoption, work reports, evidence review and cycle transitions retain their distinct meanings. Previous records remain available.</p>';
        foreach($w['system_mismatches']??[] as $m)echo '<p class="nasa-hint">'.self::e(is_string($m)?$m:json_encode($m,JSON_UNESCAPED_SLASHES)).'</p>';
        self::history($w);echo '</section>';
        echo '<footer class="card nasa-package"><div class="card-body"><h3>Keep an understandable review package</h3><div class="nasa-package-actions">';foreach(['json'=>'Download project JSON','markdown'=>'Download readable project package','context_json'=>'SE Context Pack JSON','context_markdown'=>'SE Context Pack Markdown'] as $format=>$label){self::form('nasa_export',['format'=>$format]);self::submit($label,'btn-outline-secondary');}echo '</div><p class="nasa-hint">AI output stays pending until owner adoption. Source, configuration and review limits stay with each result.</p></div></footer></div>';
    }
}
